INSERT INTO `clanci` (`id`, `datum`, `naslov`, `sazetak`, `tekst`, `slika`, `kategorija`, `arhiva`) VALUES
(2, '2026-06-22', 'Ministarstvo kulture i medija osiguralo gotovo 850 tisuća eura vizualnim umjetnicima', 'Ministarstvo kulture i medija (MKM) osiguralo je putem javnog poziva potpore vizualnim umjetnicima u iznosu od gotovo 850 tisuća eura za 376 programa poticanja stvaralaštva vizualnih umjetnika, objavilo je u utorak MKM.', 'Ministarstvo navodi kako je na ovogodišnji Javni poziv za poticanje stvaralaštva vizualnih umjetnika, koji je bio otvoren od 27. veljače do 31. ožujka, zaprimljeno 546 prijava, što je čak 18 posto više prijava nego u 2025. godini.\r\n\r\nPotpore vizualnim umjetnicima dodijeljene su u dvije kategorije - potpora stvaranju, produkciji i distribuciji radova iz područja vizualnih umjetnosti za aktivnosti: umjetničko istraživanje i edukacija umjetnika, realizacija novih radova i prezentacija rada te poticaj umjetnicima za autorski rad na samostalnoj izložbi.\r\n\r\nPrograme poticanja stvaralaštva vizualnih umjetnika prijavljene na Javni poziv razmatralo je Stručno povjerenstvo za poticanje stvaralaštva vizualnih umjetnika u Republici Hrvatskoj u 2026. u sastavu: Jasminka Babić, predsjednica, Martina Munivrana i Matko Vekić.\r\n\r\nPrijavitelji koji nisu zadovoljili formalne uvjete nisu poduprti financiranjem.', 'potpora-umjetnicima.avif', 'Kultura', 0),
(3, '2026-06-22', 'Američki i britanski mediji hvale festival u Zagrebu!', 'Cijenjeni međunarodni mediji, britanski The Independent i američki USA Today, objavili su preporuke koje INmusic i Zagreb predstavljaju međunarodnoj publici kao jedno od najzanimljivijih ljetnih iskustava u Europi ove godine, izvijestio je u utorak Festival.', 'Britanski The Independent u svom vodiču za ljetne aktivnosti u Europi preporučuje svojim čitateljima samo jedan glazbeni festival i to INmusic festival nazivajući ga u naslovu \"najboljim hrvatskim glazbenim festivalom\".\r\n\r\nList ističe dvadeset godina postojanja INmusic festivala, opisuje ga kao \'najveći hrvatski glazbeni događaj na otvorenom\' te naglašava festivalsku atmosferu uz jezero Jarun, kampiranje na festivalskoj lokaciji te spoj svjetskih headlinera i opuštenog boutique festivalskog iskustva.\r\n\r\nTaj medij ističe destinacijsku prednost INmusic festivala kao jedinog međunarodno relevantnog događaja u Zagrebu koji se održava van centra grada.\r\n\r\nAmerički USA Today u velikom ljetnom vodiču kroz Hrvatsku posebno izdvaja INmusic festival kao jedno od ključnih iskustava ljeta koje se ne propušta. U članku navodi kako \'dolazak u Zagreb u lipnju znači samo jedno – vidjeti najbolje ljetno događanje - INmusic festival\' te ističe da je festival tijekom dva desetljeća zaslužio svoje mjesto u europskom festivalskom kalendaru iz godine u godinu.\r\n\r\nPosebno se naglašava jedinstvena lokacija festivala na jarunskim otocima, pozornice uz jezero i panorama Zagreba koja festival čini jednim od vizualno i iskustveno najposebnijih glazbenih događaja u regiji, navodi INmusic ocjenjujući da je to \"odlična promocija Zagreba na zahtjevnom, ali i destinacijski ciljanom američkom tržištu\". \r\n\r\nOrganizatori smatraju da objave u međunarodnim medijima dodatno potvrđuju značaj INmusic festivala za turističku privlačnost Zagreba jer pokazuju da međunarodno prepoznat festival kao što je INmusic nije samo programski sadržaj u gradu, nego i relevantan način na koji se grad komunicira i doživljava.\r\n\r\n“Posebno nas veseli što međunarodni mediji prepoznaju Zagreb kao grad vrhunskog glazbenog događaja i jedinstvenog festivalskog iskustva. INmusic je tijekom godina postao važan dio identiteta Zagreba u europskom festivalskom prostoru”, poručuju organizatori festivala.\r\n\r\nOve godine INmusic festival obilježava 20 godina od prvog održavanja. Tijekom dva desetljeća izrastao je iz regionalnog glazbenog događaja u međunarodno priznati festival koji redovito dovodi neka od najvećih svjetskih imena alternativne i rock scene.\r\n\r\nINmusic festival #18 održat će se od 22. do 24. lipnja na zagrebačkom Jarunu, a ovogodišnji lineup predvode Gorillaz, Jack White, Kings of Leon, IDLES, Manic Street Preachers, The Flaming Lips i brojni drugi izvođači.', 'inmusic.avif', 'Kultura', 0),
(4, '2026-06-22', 'Nova sezona u Lisinskom: Svjetske zvijezde, slavljenički programi i klasika ', 'Svjetske zvijezde, slavljenički programi te orkestralna i komorna klasika obilježit će novu sezonu 2026./2027. u Koncertnoj dvorani Vatroslava Lisinskog, koja je u ponedjeljak predstavljena javnosti uz zvuke glazbe Ludwiga van Beethovena, čija se 200. obljetnica smrti obilježava sljedeće godine.', 'Ravnateljica Lisinskog Nina Čalopek podsjetila je na konferenciji za novinare na 45. obljetnicu ciklusa Lisinski subotom koji se vrlo brzo etablirao, dovodeći najveće međunarodne ansamble i pojedince.\r\n\r\nNajesen ciklus Lisinski subotom otvara Simfonijski orkestar HRT-a s dirigentom Pascalom Rophéom i velikim čelistom Gautierom Capuçonom. S orkestrom Camerata Vienna Milano nastupit će najveći harfist današnjice Xavier de Maistre.\r\n\r\nSolo recital imat će svjetska pijanistička zvijezda Nikolaj Luganski, a dolaze i Bečki simfoničari s velikim japanskim pijanistom Maom Fujitom, neprikosnovenim za Mozarta i Schuberta.\r\n\r\nOsim dvaju koncerata Simfonijskog orkestra Muzičke akademije Sveučilišta u Zagrebu (čiji su ansambli za koncert Glazba s francuskih dvorova u ovoj sezoni Lisinskog subotom dobili Diplomu „Milka Trnina“), od hrvatskih umjetnika nastupit će i Cantus Ansambl za suvremenu glazbu, koji slavi 25 godina; solisti će biti Radovan Vlatković, Ivana Srbljan i glasovirski LP Duo.\r\n\r\nNakon Švedskog komornog orkestra s klarinetistom Martinom Fröstom, dolazi znameniti orguljaš Wayne Marshall koji je već nekoliko puta oduševio publiku Lisinskog, zatim čuveni Orkestar Nacionalne akademije Santa Cecilia s dirigentom Danielom Hardingom te Simfonijski orkestar Bečkoga radija - ORF, kojim ravna Markus Poschner, a solist je violinist Nemanja Radulović.\r\n\r\nSjajnu tradiciju baltičkih zborova u novoj sezoni predstavit će Estonski nacionalni muški zbor, a za kraj ciklusa tu je još jedan legendarni ansambl – Academy of St. Martin in the Fields.\r\n\r\nPročelnica Gradskog ureda za kulturu i civilno društvo Emina Višnić naglasila je da je Grad Zagreb utrostručio ulaganja u Lisinski pa su ulaznice za prestižne koncerte četiri do pet puta jeftinije, a želja im je da kultura bude dostupna svima.\r\n\r\nČlan Papandopulo kvarteta Tomislav Žužak predstavio je koncerte Papandopulo kvarteta u novoj sezoni ciklusa Lisinski da camera na kojima će biti i nekoliko novih djela i praizvedbi.\r\n\r\nRavnateljica Čalopek dodala je da je iznimno sretna što će se gitarskom Triju Elogio, Papandopulo kvartetu i Zagrebačkim solistima od jeseni u formatu Učimo o glazbi uz... pridružiti i glasovirski kvartet - Dunja Bontek, Marija Andrejaš, Monika Leskovar i Martina Filjak.\r\n\r\nOduševljeno je o komornom ciklusu govorio i Pedro Ribeiro Rodrigues iz Trija Elogio.\r\n\r\nOsim Beethovena, kojeg će u povodu obljetnice izvoditi sva tri ansambla, Trio Elogio će se u povodu njihovih godišnjica prisjetiti Borisa Papandopula, Enriquea Granadosa, ali i 270. obljetnice rođenja Wolfganga Amadeusa Mozarta. „Mozarta bi trebalo slaviti svake godine“, nasmijao se Rodrigues.\r\n\r\nI Trio Elogio izvest će nove skladbe ili hrvatske praizvedbe, pa i naših autora Ivana Josipa Skendera i Šimuna Čarlija Botice, a ravnateljica Čalopek prokomentirala je da su djela hrvatskih skladatelja, pa i potpuno nova, snažna orijentacija Dvorane Lisinski.\r\n\r\nProdaja pretplata počela je u ponedjeljak na blagajnama Dvorane i online.', 'lisinski.avif', 'Kultura', 0),
(5, '2026-06-24', 'Hezonja: Kemija u reprezentaciji nikad nije bila bolja', 'Hrvatskoj košarkaškoj reprezentaciji, koja se od 15. lipnja u Opatiji priprema za prijateljsku utakmicu protiv Italije 24. lipnja nakon koje slijede dvije službene kvalifikacijske utakmice protiv Cipra i Izraela, priključili su se svi igrači s popisa, uključujući i Marija Hezonju i Ivicu Zupca.', '“Prije svega, Hrvatsku je uvijek lijepo vidjeti. Znamo što je ispred nas, tako da postoji velika odgovornost, kao i svaki put, u svakoj utakmici. Pripreme su već počele. Okupili smo se prije tjedan dana s jednim dijelom igrača, a danas nam se priključuju svi. Sukladno tome, atmosfera je sjajna, uvjeti su odlični i apsolutno smo svjesni pozicije u kojoj se nalazimo. Svjesni smo da tu poziciju treba potvrditi, zadržati i unaprijediti. U fazi smo skupljanja bodova. Možda to ponekad zvuči previše komercijalno, ali to je istina. Jako su nam važne obje utakmice u ovom ciklusu, kao i sve dosadašnje. Pokušat ćemo odigrati na najbolji mogući način, pobijediti i napraviti još jedan korak prema našem konačnom cilju, a to je plasman na Svjetsko prvenstvo”, izjavio je izbornik Tomislav Mijatović.\r\n\r\n“Sportaš se uvijek nada maksimalnom učinku, tako da vam nikada neću reći da sam zadovoljan bilo kojim porazom. To ne postoji. Ali ako realno sagledamo cijelu sliku, mislim da smo do sada napravili vrlo korektan posao. Međutim, znamo da možemo i moramo još bolje. S tim ciljem i tom sviješću okupljamo se i sada. Želimo ispraviti pogreške koje smo imali u posljednjem prozoru protiv Njemačke, unaprijediti dobre stvari koje su također bile prisutne te našoj publici, koja nas vjerno prati i podržava, pružiti još više razloga za ponos. Na njihovoj podršci smo iznimno zahvalni”, dodao je izbornik najavljujući utakmicu s Italijom.\r\n\r\n“Trening utakmice, kako ih ja osobno volim nazivati, odličan su pokazatelj trenutnog stanja momčadi. One predstavljaju dodatnu priliku za rad i za stvari koje ponekad ne možete dovoljno uvježbati tijekom redovitih kvalifikacijskih aktivnosti. Utakmica protiv Italije bit će sjajan test protiv vrlo kvalitetne reprezentacije. Namjerno smo odabrali takvog protivnika prije ovog prozora. Vjerujemo da će nam poslužiti za raspodjelu minutaže, isprobavanje određenih akcija i specijalnih situacija, kako u napadu tako i u obrani. Dolazi u pravom trenutku protiv ozbiljnog protivnika koji se također nalazi u kvalifikacijskom procesu. Veselimo se toj utakmici i vjerujem da će nam biti od velike koristi”, rekao je Mijatović kijeg raduje povratak reprezentativca Darija Šarića u Europu.\r\n“Dario Šarić je svakako jedan od najpotentnijih europskih igrača na pozicijama četiri i pet. On je igrač koji stvara višak i čini svaku momčad boljom. Vjerujem da će njegov dolazak u Anadolu Efes biti odličan potez i za klub i za njega osobno, a samim time i za našu reprezentaciju. Igrat će Euroligu na najvišoj razini i očekujem da bude jedan od ključnih igrača Efesa. Kada igrač dolazi u reprezentaciju iz takvog okruženja i s tako važnom ulogom u klubu, onda dolazi spreman i za veliku odgovornost u reprezentaciji. Od njega očekujemo maksimum, kao i od svih naših igrača. Pozdravljamo njegov povratak u Europu i veselimo se njegovim dobrim igrama, kako u klubu tako i u reprezentaciji”, kazao je Mijatović.\r\n\r\nHrvatski reprezentativci naglasili su kako pripreme protječu prema planu te da momčad s optimizmom očekuje prve utakmice ovog ljeta.\r\n\r\n“Volio bih otići na veliko prvenstvo, znači i meni i nama, nismo bili odavno. Nadam se da ćemo uspjeti ovo ljeto ući sa 100 posto i otići na prvenstvo”, rekao je Šarić.\r\n\r\n“Bez obzira što utakmica s Italijom nije natjecateljskog karaktera, značit će nam da uđemo svi u ritam jer nismo davno bili na terenu u punom sastavu. Očekujem dobru utakmicu, očekujem da ćemo pobijediti u utakmici na Cipru i da ćemo protiv Izraela pokušati doći do pobjede bez obzira što su nezgodna momčad”, dodao je Šarić pa se kratko osvrnuo na dosadašnji tijek kvalifikacija.\r\n\r\n“Odigrali smo dobru utakmicu u Zagrebu, u Njemačkoj u zadnjim minutama imali plus 10, mogli smo to bolje završiti, malo se uvukla nervoza u sve nas, možda prvenstveno malo u mene, ali na kraju okej, u dobroj smo situaciji. Zato ćemo probati sada dobiti ove dvije utakmice i ići u idući krug s najvećim mogućim brojem bodova. Ostat će mali žal, ali manje smo izgubili nego što smo pobijedili, tako da smo i dalje u prednosti.”\r\n\r\nIvica Zubac je također zadovoljan do sada pokazanim u kvalifikacijama.\r\n\r\n“Sve četiri utakmice koje smo igrali smo stvarno dobro izgledali, a čak i ono što smo izgubili smo odigrali i izgledali kao da možemo dobiti. Nisam nikada igrao pod trenerom Mijatovićem tako da će to biti jedno novo iskustvo zbog čega sam jako uzbuđen.  Italija je pripremna utakmica da vidimo gdje smo i što smo. Neki igrači, uključujući mene, nisu već duže vremena bili u pogonu, neki par tjedana, neki par dana, neki mjesec, neki su tek završili. Naravno da želimo pobijediti svaku utakmicu koju možemo. Bit će to jedna dobra provjera da vidimo na čemu trebamo raditi, što trebamo propraviti”, rekao je Zubac.\r\n\r\nMario Hezonja posebno ističe jako dobru atmosferu u reprezentaciji kao prednost.\r\n\r\n“Svi su na okupu, nedostaje nam par igrača zbog individualnih obaveza, svi su spremni kroz treninge i prijateljske utakmice se maksimalno vratiti na ono što radimo zimi i nastaviti pobijeđivati. Mislim da imamo fenomenalnu bazu igrača. U posljednjih nekoliko godina, otkad smo svi zajedno ovdje, izgradili smo nešto jako važno. Kemija u reprezentaciji nikad nije bila bolja i to je ono što nam najviše znači. Što se tiče ove dvije utakmice koje su pred nama, to ćemo riješiti na terenu. Nadam se da ćemo osvojiti nove bodove i nastaviti graditi ono što smo dosad napravili”, kazao je Hezonja.\r\n\r\nHrvatska utakmicu protiv Italije igra 24. lipnja u Goriziji, a onda gostuje kod Cipra 3. srpnja da bi 6. srpnja u osječkom Gradskom vrtu dočekala Izrael.', 'reprezentacija.jpg', 'Sport', 0),
(6, '2026-06-24', 'Hamilton slavi prvu pobjedu u Ferrariju!', 'Sedmerostruki svjetski prvak Lewis Hamilton stigao je do svoje prve pobjede u Ferrariju, nakon što je slavio na Velikoj nagradi Barcelone i Katalonije, sedmoj utrci ovogodišnjeg prvenstva Formule 1.', 'Hamilton je na stazi Catalunya upisao prvi trijumf nakon 685 dana i utrke u Belgiji, kada je zabilježio posljednju pobjedu za volanom Mercedesa, i to poslije diskvalifikacije tadašnjeg momčadskog kolege Georgea Russella.\r\n\r\nZa Britanca je prva pobjeda u Ferrariju, ukupno 106. u karijeri, a ujedno je postao 11. vozač koji se u Formuli 1 penjao na najvišu stepenicu pobjedničkog postolja s trima različitim momčadima. Inače, u tom su odabranom društvu, između ostalih, Kimi Räikkönen, Fernando Alonso, Sebastian Vettel, Nelson Piquet i Niki Lauda.\r\n\r\nVozač Ferrarija je tako prekinuo niz trijumfa Kimija Antonellija, koji je bio nezaustavljiv na prethodnih pet utrka, ali je zbog kvara morao odustati. Talijan je u tom trenutku držao drugu poziciju, a zbog te je situacije utrka zamalo završena iza virtualnog sigurnosnog automobila.\r\n\r\nBritanac je na kraju slavio ispred Russella, koji je na cilju imao više od 20 sekundi zaostatka, dok se na trećoj stepenici pobjedničkog postolja našao aktualni prvak Lando Norris.\r\n\r\nHamilton je na Catalunyi sasvim sigurno odvezao svoju najbolju utrku za volanom Ferrarija, a sjajna strategija i okolnosti pomogle su mu da zgrabi priliku i iskoristi je. Britanac je tri puta mijenjao gume, a na ruku mu je išla borba između vozača Mercedesa, a zatim i odustajanje Fernanda Alonsa u Aston Martinu. Zaustavljanje miljenika domaće publike pokraj staze dovelo je do razdoblja virtualnog sigurnosnog automobila, što je Hamilton iskoristio za posljednji odlazak u boks i izlazak na prvo mjesto, ispred Russella. Od tog trenutka sedmerostruki svjetski prvak samo je povećavao prednost i nitko mu nije mogao zaprijetiti do kraja utrke.\r\n\r\nIduća utrka Formule 1 vozi se za Veliku nagradu Austrije od 26. do 28. lipnja.', 'hamilton.jpg', 'Sport', 0),
(7, '2026-06-24', 'Ovako su igrači BiH navijali za Hrvatsku protiv Paname', 'Dok odbrojavaju sate do odlučujuće utakmice grupne faze protiv Katara na Svjetskom prvenstvu, reprezentativci Bosne i Hercegovine slobodno su vrijeme u Seattleu iskoristili za praćenje zbivanja na najvećoj nogometnoj smotri.', 'Nogometni savez Bosne i Hercegovine objavio je fotografiju iz hotela na kojoj se vidi nekoliko bh. reprezentativaca okupljenih ispred televizora kako zajedno, u opuštenom ozračju, prate nastup Hrvatske protiv Paname u okviru drugog kola skupine L.\r\n\r\nOve scene iz tabora Zmajeva još su jedna potvrda sjajnih odnosa koji vladaju između igrača i sportskih kolektiva iz Bosne i Hercegovine i Hrvatske. Iako su maksimalno usredotočeni na vlastite obveze i povijesni meč koji ih očekuje, bh. nogometaši pokazali su veliko zanimanje za nastupe susjeda.\r\n\r\nHrvatska je na kraju stigla do vrijedne pobjede od 1:0 pogotkom Ante Budimira, a nema sumnje da je taj rezultat obradovao i reprezentativce BiH.\r\n\r\nPred Zmajevima je sada najvažniji izazov dosadašnjeg dijela prvenstva – dvoboj protiv Katara koji izravno odlučuje o plasmanu u nokaut-fazu, a utakmica se igra večeras u 21 sat.', 'hrvatska-sp.jpg', 'Sport', 0),
(8, '2026-06-24', 'Hrvatska razbila sve pred sobom na pijesku i osigurala prolaz već prvog dana', 'Žene slavile dvaput bez izgubljenog seta, muškarci srušili Oman i Australiju za savršen učinak 4-0', 'Odlična uvertira, kako za zagrijavanje pred nogometni sraz Hrvatske i Paname, tako i perfektan početak 12. Svjetskog prvenstva u rukometu na pijesku u Zagrebu, uz Jarunsko jezero. Kako drukčije protumačiti dan u kojem je Hrvatska pobijedila – četiri puta!\r\n\r\nPodsjetimo, na ovom SP-u natječu se istodobno žene i muškarci, a budući da svaka reprezentacija u pravilu odigra i po dvije utakmice dnevno, onda je računica o četiri susreta i isto toliko pobjeda tim razumljivija.\r\n\r\nPodsjetimo, početkom utorka naše su djevojke svladale Portoriko 2-0 po setovima, dok su dečki istim učinkom preskočili Oman. Onda je stigao večernji termin.\r\n\r\nSada su djevojke imale izrazito lagan posao jer je Hrvatska igrala protiv reprezentacije Cookova otočja i dobile jasno 2-0 u setovima, odnosno 26:10 i 20:8. Već vam je po tim rezultatima jasno kakva je to utakmica bila i koliki nerazmjer u kvaliteti. Logično, doduše, jer se Cookovo otočje prvi put uopće plasiralo na SP u ovom sportu. Pobjedom nad ‘otočankama’ Hrvatska je već, dakako, osigurala prolazak skupine, a naše djevojke u srijedu u podne čekaju Španjolke i utakmica za 1. mjesto u skupini uz prenošenje maksimalnog broja bodova.\r\n\r\nDečki su pak svladali Australiju, po setovima 2-0, ali tu je već bilo ozbiljnije borbe (23:20 i 26:18). Domagoj Kuliš postigao je 13 golova, dok su po 10 pridodali Filip Goričanec i Ivan Dumenčić.\r\n\r\nOvom pobjedom i muška je reprezentacija, dvostruki uzastopni i aktualni svjetski prvaci, osigurala prolazak skupine, a u srijedu ih u 13.00 sati čeka ogled s Francuskom.', 'rukomet-na-pijesku.webp', 'Sport', 0),
(9, '2026-06-24', 'Washington nakon 16 godina imao prvi izbor, Memphis odabrao sina klasnog igrača', 'BYU strijelac s brojkama nalik Birdu postaje prvi pick u New Jerseyju, dok Top 10 pripada Amerikancima', 'NBA klub Washington Wizards uzeo je krilnog igrača AJ Dybantsa, sa sveučilišta BYU, kao prvi izbor na ovogodišnjem draftu koji je održan u New Jerseyju.\r\n\r\nOčekivano se Washington odlučio za ovog košarkaša koji je u jedinoj odigranoj sveučilišnoj sezoni ostvarivao prosjek od 25.5 poena po utakmici uz 6.8 skokova i 3.7 asistencije. Posljednje takve brojke kroz sveučilišnu karijeru imao je legendarni Larry Bird.\r\n\r\n„Ovaj izbor mi puno znači i jaka mi je odskočna daska za dalje. No, jasno mi je da je ispred mene još puno posla“, izjavio je AJ Dybantsa.\r\n\r\nWashington je treći put u povijesti imao prvi izbor na draftu, a ranije je birao Kwame Browna 2001. te Johna Walla 2010. godine.\r\n\r\nUtah Jazz je kao drugi klub birao organizatora igre Darryna Petersona sa sveučilišta Kansas, Memphis je kao treći uzeo s Dukea Camerona Boozera, sina legendarnog nekadašnjeg igrača Carlosa Boozera, dok je Chicago kao četvrti po redu odabrao Caleba Wilsona s North Caroline.\r\n\r\nMnogi američki NBA kroničari navode da bi ovogodišnji draft mogao kvalitativno biti najjači u posljednjih nekoliko godina.\r\n\r\nU zadnje vrijeme dosta je Europljana popunjavalo vodeća mjesta na NBA draftu, a ovaj put je kompletni Top 10 bio ispunjen američkim košarkašima. Prvi Europljanin na popisu bio je Španjolac Aday Mara kojeg je kao 12. uzeo Oklahoma City, dok se na 14. mjestu našao Nijemac Hannes Steinbach kojeg je izabrao Charlotte.', 'nba.jpg', 'Sport', 1),
(10, '2026-06-24', 'Robert Plant svojom je karizmom Tvrđavu sv. Mihovila pretvorio u planinu snova', 'Sa Suzi Dian i sjajnim bendom Saving Grace Plant se vratio izvorima iz kojih su svojedobno nadahnuće crpili i Page i Led Zeppelin', 'Mi smo nešto poput folk-benda, ali volimo i psihodeliju – rekao je na pozornici šibenske Tvrđave sv. Mihovila Robert Plant, govoreći o sastavu s kojim je u ponedjeljak na tom čudesnom mjestu održao treći uzastopni koncert.\r\n\r\nPublika dobnog raspona od barem jedne male bebe u majčinom naručju pa do mnogih Plantovih vršnjaka bila je oduševljena, upijala je svaku njegovu riječ i svaku pjesmu. A on, jedan od posljednjih bogova rock and rolla koji hodaju zemljom, bio je, baš kao pravi Englez, decentan, često samoironičan, a opet i mediteranski prisan, razdragan i povrh svega – zahvalan. Zahvalan što još uvijek postoji na Zemlji i pjeva pod zvjezdanim nebom, zahvalan za srdačnu podršku i ljubav koju dobiva i koja mu se s tribina vraća, zahvalan na ljepoti ambijenta.\r\n\r\nNaravno da velike zvijezde s velikim i dugim iskustvom života na sceni znaju podilaziti svakoj publici u svakom kutku svijeta. Ali, imam i ja ponešto iskustva s ove strane pozornice i tvrdim: to nije bila hinjena kurtoazija, to nije bilo ispunjavanje norme i samo jedna u nizu gaža. Pamtit ćemo dugo tu večer svi mi koji smo bili s Plantom na svetom Mihovilu, ali pamtit će je i on.\r\n\r\nRiječi zahvale koje je na kraju uputio organizatorima (agencija LAA i Tvrđava kulture Šibenik) i čitavoj ekipi koja se brinula o svakom detalju, a osobito o savršenom zvuku, bile su iskrene, kao i njegovo obećanje: vidjet ćemo se mi ovdje opet.\r\n\r\nMožda je tkogod na koncert i zalutao misleći da će doživjeti raspamećivanje stadionskog tipa zvučnim zidom koji vas udara poput kamiona i glasom pjevača kojem nije bilo premca i čije vokalne bravure i divlja sirova snaga još uvijek žive sačuvane na tolikim antologijskim snimkama. Ništa od toga. Led Zeppelin odavno ne postoji, a Robert Plant već desetljećima traje i širi mirnu, ponekad gotovo meditativnu energiju drevnog druida i barda, koji srče polako sa samog vrela života i mudrosti. Nismo raspamećeni otišli u mrak, nego smo se u najkraću noć na sve strane razišli osnaženi, raznježeni i razdragani, svjetlucavi poput ivanjskih krijesnica, poput one ekipe iz Vrgorca s kojom smo kasnije razmjenjivali dojmove na opustjeloj benzinskoj pumpi.\r\n\r\nPretposljednji pozdrav prije rastanka, s obećanjem o ponovnom susretu kojem se svi nadamo, bila je pjesma \"Going to California\". Koliko simbolike koja kao da je baš za tu večer i za to mjesto ispisana.\r\n\r\nNakon dana i godina uz ženu bez nježnosti, popušenih zaliha (zna se čega) i ispijenog vina, ispražnjeno i bolno srce kreće u potragu. Svoju \"kraljicu bez kralja za koju kažu da svira gitaru, plače i pjeva la-la-la-la...\" Plant je imao uz sebe u predivnom eteričnom liku i glasu Suzi Dian. Koja svira i harmoniku.\r\n\r\nLegenda kaže da je band Saving Grace, s kojim već dulje vrijeme surađuje i po kojem je nazvan njegov posljednji prošle godine objavljen studijski album, Plant okupio po pubovima duboke engleske provincije, tamo negdje na granici s Walesom. Tako i zvuče Tony Kelsey (gitare), Matt Worley (gitare i drugi žičani instrumenti, osobito mandolina), Oli Jefferson (bubnjevi i udaraljke) te Barney Morse-Brown čije violončelo, uz malu pomoć elektronike, učas zna postati upravo mašina za spominjanu psihodeliju.\r\n\r\nPlant se s tom sjajnom ekipom zapravo vratio izvorima koji su nadahnjivali i Pagea i Led Zeppelin. Da, to je i američki blues, ali to je osobito jedinstvena višestoljetna tradicija engleske pjesme, s još dubljim slojevima drevnih keltskih balada.\r\n\r\nRekao je Plant ponešto o tome kad se, kao, pokušavao prisjetiti koliko je stara pjesma \"As I Roved Out\".\r\n\r\nJe li to bilo sedamdesetih? – pita on.\r\n\r\nJa bih prije rekla da su to osamdesete ili devedesete. I to osamnaestog stoljeća – odgovara Dian.\r\n\r\nIznevjerene čežnje, prijevara, magla, slomljeno srce... sve to nerijetko i bez nade, ali uvijek s pronalaženjem ljepote i nove snage čak i na dnu najdubljeg očaja.\r\n\r\nDobra dva sata trajala je čarolija. Pustio je tu i tamo Robert Plant svoj glas, kao kada stari lav rikne tek toliko da mladunčad i samog sebe podsjeti na davne dane i silu koja mu je kostima. Ali njegova karizma više nije u rici. Ne treba on više obožavatelje. Treba dobro društvo dobrih ljudi za dobru glazbu i dobar život.\r\n\r\nAko niste bili u tom društvu, neće vam ništa značiti nabrajanje pjesama. Sljedeći put dođite.\r\n\r\nStojim na brežuljku svoje planine snova i govorim sebi da nije tako teško kao što se čini – otpjevao je Plant. i nije morao do Kalifornije. Ta planina snova bila je, koprenom magije ogrnuta, jedna hrid i tvrđava iznad Šibenika.', 'robert-plant.jpeg', 'Kultura', 1),
(11, '2026-06-24', 'Tomašević najavio pet velikih investicija u kulturu', 'ZAGREBAČKI gradonačelnik Tomislav Tomašević danas je predstavio pet novih kapitalnih investicija u zagrebačku kulturu vrijednih 23 milijuna eura, naglasivši kako je namjera gradske vlasti decentralizirati kulturu i \"doći s kulturom\" građanima u kvartove.', '\"Kultura nam je jedan od strateških projekata u Gradu Zagrebu. Gradovi se razlikuju primarno po kulturi, bilo da se radi o \"hardveru\", kulturnoj baštini i zgradama, bilo da se radi o \"softveru\", odnosno o kulturnim sadržajima\", rekao je Tomašević. Podsjetio je na dosadašnja gradska ulaganja u kulturu u skladu s programom razvoja kulture od 2024. do 2030.\r\n\r\nIstaknuo je projekte koji se provode i pred skorim su završetkom, uključujući obnovu Paromlina, Kina Europe, Umjetničkog paviljona, Muzeja za umjetnost i obrt, Kuće hrvatskog filma i Kazališta Komedija. Ti projekti vrijedni su 209 milijuna eura, od kojih je 131 milijun iz europskih fondova, oko 71 milijun iz zagrebačkog i oko sedam milijuna iz državnog proračuna.\r\n\r\nStiže pet novih kulturnih prostora\r\nPet novih kapitalnih investicija u kulturu: Kulturno-umjetnički centar Pluto, Muzički centar Tesarna u Gredelju, Kulturni centar Jelkovec, Interkulturni društveni centar Tržnice Trnje i Galerija Draškovićeva vrijedne su oko 23 milijuna eura, kazao je Tomašević, dodavši kako će se, prema sadašnjem planu, ti projekti financirati isključivo iz gradskog proračuna.\r\n\r\nPročelnica Gradskog ureda za kulturu i civilno društvo Emina Višnić kao najvrjedniji projekt izdvojila je Centar Pluto na prostoru bivše tvornice u Ulici Ljudevita Posavskog, gdje se planira veliki galerijski prostor,  prvi zagrebački suvremeni kunsthalle s nizom popratnih sadržaja, procijenjene vrijednosti 11,5 milijuna eura bez PDV-a.\r\n\r\nNajavila je kako će zaštićena zgrada Tesarne u kompleksu Gredelj biti prenamijenjena u koncertno-edukacijski prostor, odnosno muzički centar za razvoj nove autorske glazbe te da je za taj projekt planirano 2,5 milijuna eura.\r\n\r\nKultura stiže i u Sesvete i Staro Trnje\r\nGradsko naselje Sopnica-Jelkovec u Sesvetama dobit će centar kulturnog i društvenog života s velikom dvoranom te prostorima za radionice i druge programe. Novi sadržaji planirani su i u Starom Trnju, gdje će se na prostoru bivše tržnice urediti Interkulturni društveni centar s galerijom i manjom dvoranom.\r\n\r\nTi projekti vrijedni su 4,2, odnosno 3,9 milijuna eura, a kao peti od najavljenih projekata predstavljena je nova gradska umjetnička galerija u Draškovićevoj ulici za koju je planirano oko 800.000 eura. Završetkom ovih projekata Zagrepčani će dobiti pet novih, suvremeno opremljenih prostora kulture i umjetnosti na ukupno oko 10.000 četvornih metara.\r\n\r\n\"Realizacija ovih novih kapitalnih projekata dio je provedbe gradske kulturne strategije Program razvoja kulture 2024. - 2030., koja je trenutačno na trećini razdoblja provedbe, a čiji je cilj sažet u sloganu \"Kultura koja stvara grad, grad koji živi kulturu\". Upravljanje ovim prostorima temeljit će se na participativnom modelu\", kazala je Višnić.\r\n\r\nObnavljaju se kina i kulturni centri\r\nNa predstavljanju je istaknuto i da je pokrenuta obnova Kina Tuškanac te da je u pripremi rekonstrukcija i dogradnja četiri kulturna centra: Novi Zagreb, Ribnjak, Maksimir i Dubrava. Procjena vrijednosti tih projekata je 38,7 milijuna eura, a također će biti financirani iz gradskog proračuna.\r\n\r\nU narednih nekoliko godina Grad Zagreb, uz 70,8 milijuna eura koliko trenutačno investira u kapitalne projekte u kulturi, uložit će još 62 milijuna eura u nove kapitalne investicije u kulturi, odnosno ukupno više od 132 milijuna eura u razdoblju 2024. - 2030., rečeno je.', 'tomasevic.jpg', 'Kultura', 0);

